def find_minimal_edit(s_in, s_out):
    """Simplified version to understand the edits"""
    # Find first difference
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            # Check if we're inserting or replacing
            if len(s_in) < len(s_out):
                return (c_in, c_out, i)  # This is an insertion
            elif len(s_in) > len(s_out):
                return (c_in, c_out, i)  # This is a deletion  
            else:
                return (c_in, c_out, i)  # This is a replacement

    # If strings are same length and no differences found
    if len(s_in) != len(s_out):
        # Handle length differences
        if len(s_in) < len(s_out):
            # Insertion case
            return (s_in[-1], s_out[-1], len(s_in)-1)  # Insert at end
        else:
            # Deletion case  
            return (s_in[-1], s_out[-1], len(s_out)-1)  # Delete at end
    return ("", "", -1)  # No change

inputs = ['whubf', 'vchggg', 'eywi', 'cuhawh', 'wcu']
outputs = ['ehubuy', 'dicchggg', 'eyei', 'cuhaeh', 'ecu']

